#include <vector>
#include <unordered_map>

class Solution {
public:
    bool isPossibleToSplit(std::vector<int>& nums) {
        std::unordered_map<int, int> cnt;
        for (int x : nums) {
            cnt[x]++;
            if (cnt[x] > 2) return false;
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean isPossibleToSplit(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) {
            int c = cnt.getOrDefault(x, 0) + 1;
            if (c > 2) return false;
            cnt.put(x, c);
        }
        return true;
    }
}

var isPossibleToSplit = function(nums) {
    const cnt = new Map();
    for (const x of nums) {
        const c = (cnt.get(x) || 0) + 1;
        if (c > 2) return false;
        cnt.set(x, c);
    }
    return true;
};
